package com.sami.app.purchasing.service;
import com.sami.app.common.exception.*; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.inventory.publicapi.InventoryStockOperations; import com.sami.app.organization.service.*; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class GoodsReceiptService { private final JdbcTemplate jdbc; private final TenantContext tenants; private final OrganizationScopeService scope; private final InventoryStockOperations inventory; private final FoundationAuditService audit;
 @Transactional public Map<String,Object> create(Long company,Long branch,Long purchaseOrderId,Long warehouse,List<Map<String,Object>> lines,String notes){Long t=tenants.requireTenantId();scope.requireScope(company,branch);Map<String,Object> po=loadPo(t,purchaseOrderId);if(!"APPROVED".equals(po.get("status")))throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Purchase order must be approved");if(lines==null||lines.isEmpty())throw new ApiException(ErrorCode.VALIDATION_FAILED,"Receipt requires items");String n="GR-"+jdbc.queryForObject("select nextval('goods_receipt_number_seq')",Long.class);Long id=jdbc.queryForObject("insert into goods_receipts(tenant_id,company_id,branch_id,purchase_order_id,supplier_id,receipt_number,warehouse_id,notes) values(?,?,?,?,?,?,?,?) returning id",Long.class,t,company,branch,purchaseOrderId,po.get("supplier_id"),n,warehouse,notes);List<InventoryStockOperations.ReceiptLine> stock=new ArrayList<>();for(Map<String,Object> l:lines){Long pol=((Number)l.get("purchaseOrderLineId")).longValue();BigDecimal q=new BigDecimal(l.get("receivedQuantity").toString()),cost=new BigDecimal(l.get("unitCost").toString());Map<String,Object> row=jdbc.queryForMap("select product_id,quantity from purchase_order_lines where tenant_id=? and id=? and purchase_order_id=?",t,pol,purchaseOrderId);if(q.signum()<=0||q.compareTo((BigDecimal)row.get("quantity"))>0)throw new ApiException(ErrorCode.VALIDATION_FAILED,"Received quantity exceeds ordered quantity");jdbc.update("insert into goods_receipt_lines(tenant_id,receipt_id,purchase_order_line_id,product_id,received_quantity,unit_cost) values(?,?,?,?,?,?)",t,id,pol,row.get("product_id"),q,cost);stock.add(new InventoryStockOperations.ReceiptLine(pol,((Number)row.get("product_id")).longValue(),q,cost,List.of()));}inventory.receivePurchase(new InventoryStockOperations.PurchaseReceiptCommand(warehouse,purchaseOrderId,id,stock));jdbc.update("update goods_receipts set status='CONFIRMED',updated_at=now() where id=? and tenant_id=?",id,t);audit.record(t,company,branch,"GOODS_RECEIPT",id,"CONFIRMED","Goods receipt confirmed",Map.of("purchaseOrderId",purchaseOrderId));return get(id);}
 private Map<String,Object> loadPo(Long t,Long id){try{return jdbc.queryForMap("select * from purchase_orders where tenant_id=? and id=?",t,id);}catch(Exception e){throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND,"Purchase order not found");}}
 @Transactional(readOnly=true) public Map<String,Object> get(Long id){Long t=tenants.requireTenantId();Map<String,Object> r;try{r=jdbc.queryForMap("select * from goods_receipts where tenant_id=? and id=?",t,id);}catch(Exception e){throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND,"Goods receipt not found");}scope.requireScope(((Number)r.get("company_id")).longValue(),((Number)r.get("branch_id")).longValue());r.put("lines",jdbc.queryForList("select * from goods_receipt_lines where tenant_id=? and receipt_id=?",t,id));return r;}
 @Transactional(readOnly=true) public List<Map<String,Object>> list(){Long t=tenants.requireTenantId();var c=scope.current();if(c.companyId()==null)return List.of();return c.branchId()==null?jdbc.queryForList("select * from goods_receipts where tenant_id=? and company_id=? order by received_at desc",t,c.companyId()):jdbc.queryForList("select * from goods_receipts where tenant_id=? and company_id=? and branch_id=? order by received_at desc",t,c.companyId(),c.branchId());}
}
